// Pick the next un-used topic. We track used slugs in static data.
const used = $workflow.staticData.global.usedSlugs ??= [];
const queue = $input.first().json;
const next = queue.find((t) => !used.includes(t.slug));
if (!next) {
  throw new Error('Topic queue exhausted. Add more topics to cortisol-topic-queue.json.');
}
used.push(next.slug);
return [{ json: next }];

// Extract the MDX text from Claude's response
const body = $input.first().json;
const mdx = body.content?.[0]?.text ?? '';
const topic = $('Pick next topic').first().json;

if (!mdx.includes('---')) {
  throw new Error('Claude did not return valid MDX frontmatter.');
}

return [{
  json: {
    slug: topic.slug,
    title: topic.title,
    primaryKeyword: topic.primaryKeyword,
    mdx,
    base64Mdx: Buffer.from(mdx, 'utf-8').toString('base64'),
    path: `src/content/blog/${topic.slug}.mdx`,
  }
}];
